def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def csvhash(x,cols):return hashlib.sha256(x.select(cols).sort(cols).write_csv().encode()).hexdigest()
def sethash(x,col):return csvhash(x.unique(col),[col])
def fold(t):return int(hashlib.sha256((SALT+t).encode()).hexdigest()[:16],16)%2
def bit(t,o,j,s):return int(hashlib.sha256(f'private-fast|{s}|{o}|{j}|{t}'.encode()).hexdigest(),16)&1
