 assert csvhash(tr,K)==prior['train_keys'] and csvhash(he,K)==prior['held_keys'] and sethash(tr,'table_id')==prior['train_tables'] and sethash(he,'table_id')==prior['held_tables'] and sethash(tr,'actor_id')==prior['train_actors'] and sethash(he,'actor_id')==prior['held_actors'] and sethash(tr,'hand_id')==prior['train_hands'] and sethash(he,'hand_id')==prior['held_hands'];tr=tr.with_columns(pl.Series('private_surprise',tr['partner_strength'].to_numpy()-pred));he=he.with_columns(pl.Series('private_surprise',he['partner_strength'].to_numpy()-pkg['strength_full'].predict(he.select(inputs).to_numpy())));probs={};mods={};Xh=he.select(inputs+['private_surprise']).to_numpy();members={}
 for name,val in [('target',1),('normal',0)]:
  z,w=weights(tr.filter(pl.col('label')==val));assert set(z['action_class'])=={0,1,2,3} and time.monotonic()<deadline;m=model().fit(z.select(inputs+['private_surprise']).to_numpy(),z['action_class'].to_numpy(),sample_weight=w);assert np.array_equal(m.classes_,np.arange(4));q=m.predict_proba(Xh);assert np.isfinite(q).all() and (q>=0).all() and (q<=1).all() and np.allclose(q.sum(1),1,atol=1e-6);probs[name]=q;mods[name]=m;mp=H/f'train_membership_outer{o}_pipeline{j}_{name}.parquet';assert not mp.exists();z.select(*K,'table_id','actor_id').with_columns(pl.Series('fit_weight',w)).write_parquet(mp);members[name]={'rows':z.height,'pairs':z['pair_id'].n_unique(),'sha256':sha(mp)}
 ap=H/f'action_predictions_outer{o}_pipeline{j}.parquet';assert not ap.exists();out=he.select(*K,'table_id','actor_id','action_class');out=out.with_columns(*[pl.Series(f'target_p{k}',probs['target'][:,k]) for k in range(4)],*[pl.Series(f'normal_p{k}',probs['normal'][:,k]) for k in range(4)]);out.write_parquet(ap);members['action_predictions_sha256']=sha(ap);rp=H/f'policy_models_outer{o}_pipeline{j}.joblib';assert not rp.exists();joblib.dump(mods,rp);replay=joblib.load(rp)['target'].predict_proba(Xh);assert np.array_equal(replay,probs['target']);members['models_sha256']=sha(rp);members['target_reload_replay_exact']=True
