 old=json.loads((PC/'CPU_RECEIPT.json').read_text());assert old['manifest_sha256']==sha(PC/'MANIFEST.json');lm=json.loads((PL/'MANIFEST.json').read_text());inputs=lm['inputs'];paths=[P/k for k in lm['sources'] if k.startswith('reports/conditional-action-experiment/action-cache/')];d=pl.read_parquet(paths).join(pl.read_parquet(PL/'row_membership.parquet').select(*K,'actor_id'),on=K,validate='1:1').join(pl.read_csv(P/'data/development_labels.csv').select('pair_id','label'),on='pair_id');cap=pl.read_parquet(PL/'capped_training_keys.parquet').select(K);tabs=sorted(d['table_id'].unique().to_list());fm={t:fold(t) for t in tabs};raw=pl.read_parquet(P/'Claude Version/experiments/crossphase_20260911/lab_on_dev.parquet').with_columns(pl.Series('f',[fold(t) for t in pl.read_parquet(P/'Claude Version/experiments/crossphase_20260911/lab_on_dev.parquet')['table_id']]));receipts=[]
